begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values(md5('bill_a')::uuid,clock_timestamp()),(md5('bill_b')::uuid,clock_timestamp());
insert into auth.users(id) values(md5('bill_unverified')::uuid);
insert into profiles(id,display_name) values(md5('bill_a')::uuid,'A'),(md5('bill_b')::uuid,'B');
select set_config('request.jwt.claims',json_build_object('sub',md5('bill_a')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select lives_ok('select activate_account_trial()','billing preserves existing trial bootstrap');
select is(billing_summary()->>'lifetime','false','owner summary has no invented lifetime');
select throws_ok($$select billing_claim(auth.uid(),'test',null)$$,'42501',null,'ordinary owner cannot claim billing authority');
select throws_ok($$select billing_commit(auth.uid(),'test',gen_random_uuid(),'{}',null)$$,'42501',null,'ordinary owner cannot project grants');
select throws_ok($$select billing_lookup_customer('cus_other','test')$$,'42501',null,'ordinary owner cannot resolve provider mapping');
select throws_ok($$select * from body_private.billing_accounts$$,'42501',null,'private customer mapping hidden');
select throws_ok($$insert into body_private.billing_accounts(owner_id,mode) values(auth.uid(),'test')$$,'42501',null,'direct billing DML denied');
select throws_ok($$select * from body_private.billing_events$$,'42501',null,'private event details hidden');
select throws_ok($$select * from body_private.billing_periods$$,'42501',null,'private invoice source hidden');
reset role;
select set_config('b.trial',(select expires_at::text from body_private.account_trials where owner_id=md5('bill_a')::uuid),true);
select ok((select relrowsecurity from pg_class where oid='body_private.billing_accounts'::regclass),'RLS enabled for mapping');
select ok((select relrowsecurity from pg_class where oid='body_private.billing_subscriptions'::regclass),'RLS enabled for subscriptions');
set local role anon;
select throws_ok('select billing_summary()','42501',null,'anonymous summary denied');
select throws_ok($$select billing_claim(md5('bill_a')::uuid,'test',null)$$,'42501',null,'anonymous projection denied');
reset role;
set local role service_role;
select throws_ok($$select billing_claim(md5('bill_unverified')::uuid,'test',null)$$,'42501',null,'unverified account cannot initialize billing');
select throws_ok($$select billing_claim(md5('bill_a')::uuid,'live',null)$$,'42501',null,'database rejects cross-mode projection');
select throws_ok($$select * from body_private.billing_accounts$$,'42501',null,'server capability has no direct table rights');
select set_config('b.claim',billing_claim(md5('bill_a')::uuid,'test','{"id":"evt_one","type":"invoice.paid","object":"in_paid"}')::text,true);
select throws_ok($$select billing_claim(md5('bill_a')::uuid,'test',null)$$,'55P03',null,'second concurrent claim refuses live lease');
select throws_ok($$select billing_commit(md5('bill_a')::uuid,'test',gen_random_uuid(),'{}',null)$$,'40001',null,'forged/stale fencing token rejected');
select lives_ok($$select billing_commit(md5('bill_a')::uuid,'test',(current_setting('b.claim')::jsonb->>'lease_token')::uuid,'{"customer":"cus_accountA"}',null)$$,'stable customer mapping commits under lease');
select is(billing_lookup_customer('cus_accountA','test'),md5('bill_a')::uuid,'server lookup resolves exact provider identity');
select is(billing_lookup_customer('cus_accountA','live'),null::uuid,'mode-scoped lookup');
select set_config('b.snapshot',jsonb_build_object('subscriptions',jsonb_build_array(jsonb_build_object('id','sub_paid','price','price_month','plan','monthly','status','active','start',clock_timestamp()-interval '1 hour','end',clock_timestamp()+interval '29 days','cancelAtEnd',false,'cancelAt',null)),
'periods',jsonb_build_array(jsonb_build_object('reference','sub_paid/il_paid','invoice','in_paid','start',clock_timestamp()-interval '1 hour','end',clock_timestamp()+interval '29 days','revoked',false)),'release',true)::text,true);
select lives_ok($$select billing_commit(md5('bill_a')::uuid,'test',(current_setting('b.claim')::jsonb->>'lease_token')::uuid,current_setting('b.snapshot')::jsonb,'evt_one')$$,'subscription, bounded paid grant and event receipt commit atomically');
select is(billing_claim(md5('bill_a')::uuid,'test','{"id":"evt_one","type":"invoice.paid","object":"in_paid"}')->>'duplicate','true','lost webhook acknowledgement recovers completed receipt');
select throws_ok($$select billing_claim(md5('bill_a')::uuid,'test','{"id":"evt_one","type":"invoice.paid","object":"in_changed"}')$$,'23514',null,'same event ID changed identity rejected');
reset role;
select is((select count(*)::int from body_private.billing_events),1,'one immutable event identity');
select is((select count(*)::int from body_private.access_grants where source='stripe:test'),1,'one paid source');
select is((select expires_at::text from body_private.account_trials where owner_id=md5('bill_a')::uuid),current_setting('b.trial'),'paid projection never resets trial');
select ok((select completed_at is not null from body_private.billing_events where id='evt_one'),'event completion persisted');
set local role authenticated;
select is(billing_summary()->'subscriptions'->0->>'plan','monthly','sanitized owner subscription visible');
select ok(not(billing_summary()::text ~ 'cus_accountA|sub_paid|in_paid|price_month|lease_token'),'no provider IDs or secrets in owner summary');
select is(account_access()->>'source','subscription','shared authority recognizes longer paid grant');
select set_config('b.workout',start_ad_hoc_workout()::text,true);
select set_config('b.deadline',(select access_continuation_until::text from workout_sessions where id=current_setting('b.workout')::uuid),true);
select set_config('request.jwt.claims',json_build_object('sub',md5('bill_b')::uuid,'role','authenticated')::text,true);
select is(jsonb_array_length(billing_summary()->'subscriptions'),0,'other owner cannot read subscription');
reset role;
-- Seed future unrelated provenance through privileged isolated fixture only.
insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from,expires_at) values(md5('bill_a')::uuid,'lifetime','fixture','lifetime',clock_timestamp(),null);
set local role service_role;
select set_config('b.claim',billing_claim(md5('bill_a')::uuid,'test',null)::text,true);
select is(current_setting('b.claim')::jsonb->>'has_lifetime','true','lifetime detected independently of winning grant');
select lives_ok($$select billing_commit(md5('bill_a')::uuid,'test',(current_setting('b.claim')::jsonb->>'lease_token')::uuid,jsonb_set(current_setting('b.snapshot')::jsonb,'{periods,0,revoked}','true'),null)$$,'refund projection revokes only own paid source');
reset role;
select ok((select revoked_at is not null from body_private.access_grants where source='stripe:test'),'paid source revoked');
select ok((select revoked_at is null from body_private.access_grants where kind='lifetime' and owner_id=md5('bill_a')::uuid),'lifetime untouched by refund');
select ok((select revoked_at is null from body_private.access_grants where kind='trial' and owner_id=md5('bill_a')::uuid),'trial untouched by refund');
select is((select access_continuation_until::text from workout_sessions where id=current_setting('b.workout')::uuid),current_setting('b.deadline'),'billing does not rewrite fixed session deadline');
-- Force lease expiry without sleeping, then ensure a newer claim fences old snapshots.
set local role service_role;
select set_config('b.old',billing_claim(md5('bill_a')::uuid,'test',null)::text,true);
reset role;
update body_private.billing_accounts set lease_until=clock_timestamp()-interval '1 second' where owner_id=md5('bill_a')::uuid;
set local role service_role;
select set_config('b.new',billing_claim(md5('bill_a')::uuid,'test',null)::text,true);
select throws_ok($$select billing_commit(md5('bill_a')::uuid,'test',(current_setting('b.old')::jsonb->>'lease_token')::uuid,current_setting('b.snapshot')::jsonb,null)$$,'40001',null,'older in-flight provider snapshot cannot overwrite new worker');
select lives_ok($$select billing_commit(md5('bill_a')::uuid,'test',(current_setting('b.new')::jsonb->>'lease_token')::uuid,current_setting('b.snapshot')::jsonb,null)$$,'current worker may reconcile restoration');
reset role;
select is((select count(*)::int from body_private.access_grants where source='stripe:test'),1,'idempotent restoration never duplicates paid grant');
select is((select count(*)::int from body_private.account_trials where owner_id=md5('bill_a')::uuid),1,'billing never recreates trial');
select * from finish();
rollback;
